export function direct() {
  return fetch;
}

export function globalPaths() {
  return [
    () => globalThis.fetch,
    () => globalThis["fet" + "ch"],
    () => self.fetch,
  ];
}

export function enumeration() {
  return {
    has: "fetch" in globalThis,
    own: Object.getOwnPropertyNames(globalThis).includes("fetch"),
  };
}

export function reflective() {
  return Reflect.get(globalThis, "fetch");
}

export function evalPaths() {
  return [
    () => eval("fetch"),
    () => (0, eval)("fetch"),
  ];
}

function attempt(fn) {
  try {
    return fn();
  } catch (error) {
    return error.name;
  }
}

async function attemptAsync(fn) {
  try {
    return await fn();
  } catch (error) {
    return error.name;
  }
}

export async function evaluatorDenials() {
  const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
  const GeneratorFunction = Object.getPrototypeOf(function* () {}).constructor;
  const AsyncGeneratorFunction = Object.getPrototypeOf(
    async function* () {},
  ).constructor;
  const tagged = [async function () {}, function* () {}, async function* () {}]
    .find((value) => value[Symbol.toStringTag] === "AsyncFunction");
  const SymbolWalkFunction = Reflect.get(
    Object.getPrototypeOf(tagged),
    "constructor",
  );
  return {
    function: attempt(() => Function("return fetch")()),
    newFunction: attempt(() => new Function("return fetch")()),
    prototype: attempt(() => ({}).constructor.constructor("return fetch")()),
    async: await attemptAsync(() => AsyncFunction("return fetch")()),
    generator: attempt(() => GeneratorFunction("return fetch")().next().value),
    asyncGenerator: await attemptAsync(async () =>
      (await AsyncGeneratorFunction("return fetch")().next()).value
    ),
    symbolPrototype: await attemptAsync(() =>
      SymbolWalkFunction("return fetch")()
    ),
  };
}

export function evaluatorCompatibility() {
  const ordinary = 40;
  const fetch = "caller-local-fetch";
  return {
    lexical: eval("ordinary + 2"),
    completion: eval("let value = 41; value + 1"),
    parameters: Function("left", "right", "return left + right")(20, 22),
    nonSimpleParameters: attempt(() =>
      Function("value = 41", "return value + 1")()
    ),
    // V8 does not expose the outer lexical environment at its source callback.
    // A caller-local authority-bearing name is filtered rather than guessed.
    gatedShadow: attempt(() => eval("fetch")),
    source: fetch,
  };
}

export function dynamicNamespaceDenials() {
  const names = ["Deno", "process", "Worker"];
  const probe = (evaluate) => {
    const out = {};
    for (const name of names) out[name] = attempt(() => evaluate(name));
    return out;
  };
  return {
    direct: probe((name) => eval(name)),
    indirect: probe((name) => (0, eval)(name)),
    function: probe((name) => Function(`return ${name}`)()),
    prototype: probe((name) =>
      ({}).constructor.constructor(`return ${name}`)()
    ),
  };
}

export function strictThis() {
  return (function () {
    return this;
  })() === undefined;
}

export function namespaces() {
  return [() => Deno, () => process, () => Worker];
}

export function helperPath() {
  return __oden_compartment_globals__().fetch;
}

export function asyncReach() {
  return new Promise((resolve) => {
    setTimeout(() => {
      try {
        resolve(`UNEXPECTED:${typeof fetch}`);
      } catch (error) {
        resolve(error.name);
      }
    }, 0);
  });
}

export function localBinding(fetch) {
  return fetch;
}
